-- Reference canonical store, not an installed migration or socket queue.
PRAGMA foreign_keys=ON;
CREATE TABLE rooms(id TEXT PRIMARY KEY, generation TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('DRAFT','LIVE','ENDED')), revision INTEGER NOT NULL CHECK(revision>0), next_sequence INTEGER NOT NULL CHECK(next_sequence>0), low_sequence INTEGER NOT NULL CHECK(low_sequence>0), config_json TEXT NOT NULL CHECK(json_valid(config_json)), UNIQUE(id,generation), CHECK(low_sequence<=next_sequence));
CREATE TABLE room_events(room_id TEXT NOT NULL, generation TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>0), event_type TEXT NOT NULL CHECK(event_type IN('score-set','status-set','announcement','room-ended')), canonical_json TEXT NOT NULL CHECK(json_valid(canonical_json) AND length(CAST(canonical_json AS BLOB))<=8192), digest TEXT NOT NULL, accepted_at INTEGER NOT NULL, PRIMARY KEY(room_id,generation,sequence), FOREIGN KEY(room_id,generation) REFERENCES rooms(id,generation));
CREATE TABLE snapshots(room_id TEXT PRIMARY KEY REFERENCES rooms(id), generation TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>=0), state_json TEXT NOT NULL CHECK(json_valid(state_json)), digest TEXT NOT NULL);
CREATE TABLE publish_receipts(publisher_id TEXT NOT NULL, request_key TEXT NOT NULL, room_id TEXT NOT NULL REFERENCES rooms(id), generation TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>0), request_digest TEXT NOT NULL, response_json TEXT NOT NULL CHECK(json_valid(response_json)), PRIMARY KEY(publisher_id,request_key));
CREATE TABLE workers(id TEXT PRIMARY KEY, generation INTEGER NOT NULL CHECK(generation>0), state TEXT NOT NULL CHECK(state IN('STARTING','READY','DRAINING','UNAVAILABLE','STOPPED')), last_contact_at INTEGER NOT NULL);
CREATE TABLE capacity_grants(id TEXT PRIMARY KEY, worker_id TEXT NOT NULL REFERENCES workers(id), generation INTEGER NOT NULL CHECK(generation>0), slots INTEGER NOT NULL CHECK(slots>0), used_slots INTEGER NOT NULL CHECK(used_slots>=0), deadline INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN('ACTIVE','RELEASED','EXPIRED')), CHECK(used_slots<=slots));
CREATE TABLE sessions(id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id), current_generation INTEGER NOT NULL CHECK(current_generation>0), worker_id TEXT NOT NULL REFERENCES workers(id), grant_id TEXT NOT NULL REFERENCES capacity_grants(id), state TEXT NOT NULL CHECK(state IN('ACTIVE','DISCONNECTED','SUPERSEDED')), last_applied_sequence INTEGER NOT NULL CHECK(last_applied_sequence>=0));
CREATE TABLE ownership_history(session_id TEXT NOT NULL REFERENCES sessions(id), generation INTEGER NOT NULL CHECK(generation>0), worker_id TEXT NOT NULL REFERENCES workers(id), grant_id TEXT NOT NULL REFERENCES capacity_grants(id), state TEXT NOT NULL CHECK(state IN('ACTIVE','SUPERSEDED','CLOSED')), PRIMARY KEY(session_id,generation));
CREATE TABLE routing_maps(version INTEGER PRIMARY KEY CHECK(version>0), canonical_json TEXT NOT NULL CHECK(json_valid(canonical_json)), digest TEXT NOT NULL);
CREATE TABLE active_map(id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL REFERENCES routing_maps(version), revision INTEGER NOT NULL CHECK(revision>0));
CREATE TABLE control_receipts(actor TEXT NOT NULL, operation TEXT NOT NULL, target TEXT NOT NULL, request_key TEXT NOT NULL, digest TEXT NOT NULL, response_json TEXT NOT NULL CHECK(json_valid(response_json)), PRIMARY KEY(actor,operation,target,request_key));
CREATE TABLE operator_audit(sequence INTEGER PRIMARY KEY CHECK(sequence>0), actor TEXT NOT NULL, room_id TEXT REFERENCES rooms(id), action TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE INDEX grant_expiry ON capacity_grants(deadline) WHERE state='ACTIVE';
CREATE INDEX worker_sessions ON sessions(worker_id,state);
-- Atomic domain guards enforce generation/time, aggregate reserved capacity,
-- contiguous publication/snapshot sequence and complete routing-map activation.
-- Network sends and approximate presence are not transactional publication.
